CREATE TABLE IF NOT EXISTS indonesia_regions (
    code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    parent_code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    name VARCHAR(100) NOT NULL,
    level ENUM('province', 'regency', 'district', 'village') NOT NULL,
    PRIMARY KEY (code),
    KEY idx_indonesia_regions_parent_level_name (parent_code, level, name),
    KEY idx_indonesia_regions_level_name (level, name),
    CONSTRAINT fk_indonesia_regions_parent
        FOREIGN KEY (parent_code) REFERENCES indonesia_regions (code)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE parent_code=VALUES(parent_code), name=VALUES(name), level=VALUES(level);

