ALTER TABLE kos_buildings
    ADD COLUMN province_code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL AFTER address,
    ADD COLUMN regency_code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL AFTER province_code,
    ADD COLUMN district_code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL AFTER regency_code,
    ADD COLUMN village_code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL AFTER district_code,
    ADD COLUMN street_name TEXT NULL AFTER village_code,
    ADD COLUMN address_rt VARCHAR(10) NULL AFTER street_name,
    ADD COLUMN address_rw VARCHAR(10) NULL AFTER address_rt,
    ADD COLUMN address_block VARCHAR(50) NULL AFTER address_rw,
    ADD KEY idx_kos_buildings_province (province_code),
    ADD KEY idx_kos_buildings_regency (regency_code),
    ADD KEY idx_kos_buildings_district (district_code),
    ADD KEY idx_kos_buildings_village (village_code),
    ADD CONSTRAINT fk_kos_buildings_province FOREIGN KEY (province_code) REFERENCES indonesia_regions (code),
    ADD CONSTRAINT fk_kos_buildings_regency FOREIGN KEY (regency_code) REFERENCES indonesia_regions (code),
    ADD CONSTRAINT fk_kos_buildings_district FOREIGN KEY (district_code) REFERENCES indonesia_regions (code),
    ADD CONSTRAINT fk_kos_buildings_village FOREIGN KEY (village_code) REFERENCES indonesia_regions (code);

ALTER TABLE users
    ADD COLUMN province_code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL AFTER address,
    ADD COLUMN regency_code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL AFTER province_code,
    ADD COLUMN district_code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL AFTER regency_code,
    ADD COLUMN village_code VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL AFTER district_code,
    ADD COLUMN street_name TEXT NULL AFTER village_code,
    ADD COLUMN address_rt VARCHAR(10) NULL AFTER street_name,
    ADD COLUMN address_rw VARCHAR(10) NULL AFTER address_rt,
    ADD COLUMN address_block VARCHAR(50) NULL AFTER address_rw,
    ADD KEY idx_users_province (province_code),
    ADD KEY idx_users_regency (regency_code),
    ADD KEY idx_users_district (district_code),
    ADD KEY idx_users_village (village_code),
    ADD CONSTRAINT fk_users_province FOREIGN KEY (province_code) REFERENCES indonesia_regions (code),
    ADD CONSTRAINT fk_users_regency FOREIGN KEY (regency_code) REFERENCES indonesia_regions (code),
    ADD CONSTRAINT fk_users_district FOREIGN KEY (district_code) REFERENCES indonesia_regions (code),
    ADD CONSTRAINT fk_users_village FOREIGN KEY (village_code) REFERENCES indonesia_regions (code);
